'use strict';

const debug = require('debug')('alipay.configclient:NProtocolPacket');
const NProtocolElementUid = require('./NProtocolElementUid');

const NProtocolPacket = Object.create(null);

module.exports = NProtocolPacket;

NProtocolPacket.readObject = function(io, obj) {
  io.readBlockHeader();

  const count = io.readInt();			// Read number of elements
  const $ = obj.$;
  $.elements = [];
  const last = count - 1;
  for (let i = 0; i <= last; i++) {
    io.readInt();
    const element = io.readObject();
    $.elements.push(element);
    if (i !== last) {
      // block data mode
      io.readBlockHeader();
      // console.log(io.readBytes(2))
    }
  }

  $.connId = io.readObject();
  $.ids = io.readObject();

  // block data mode
  io.readBlockHeader();
  // console.log(io.readBytes(2))

  $.ispushed = io.readBoolean();
  $.isTempElement = io.readBoolean();
  $.timeStamp = io.readLong().toString();
  if (!$.attribute) {
    $.attribute = {};
  }
  // console.log(io.in.get(io.in.position(), 100))
  return obj;
};

NProtocolPacket.writeObject = function(io, obj) {
  const $ = obj.$;
  const count = $.elements.length;
  io.writeBlockHeader(8);
  io.writeInt(count);				// Write number of elements
  const last = count - 1;
  for (let i = 0; i < count; i++) {
    const element = $.elements[i];

    debug('element.$class: %s, value: %s', element.$class.name, NProtocolElementUid[element.$class.name]);

    io.writeInt(NProtocolElementUid[element.$class.name]);
    io.writeObject(element);
    if (i !== last) {
      // block data mode
      io.writeBlockHeader(4);
    }
  }
  io.writeObject($.connId);
  io.writeObject($.ids);

  // write block header
  io.writeBlockHeader(10);

  io.writeBoolean($.ispushed);
  io.writeBoolean($.isTempElement);
  io.writeLong($.timeStamp || nanoTime());
};

function nanoTime() {
  return Date.now() + '000000';
}
